// ----------------------------------------------------------------------------
//  Memory writing
// ----------------------------------------------------------------------------

// write_memory: see neid_port.h

static inline uint32_t readInsn(uint64_t addr) {
	return *(uint32_t*)(addr + _dyld_get_image_vmaddr_slide(0));
}

// Writing ~4,300 instructions one by one through MSHookMemory takes over 20 s,
// and iOS kills the app at launch (watchdog 0x8badf00d). So writes are queued
// and applied in a few large ranges by flushPatches().
struct PendingInsn { uint64_t addr; uint32_t insn; };
static std::vector<PendingInsn>* gPending = nullptr;

static inline bool writeInsn(uint64_t addr, uint32_t insn) {
	if (gPending) { gPending->push_back({addr, insn}); return true; }
	return write_memory((void*)(addr + _dyld_get_image_vmaddr_slide(0)), &insn, 4);
}

static void beginPatches() {
	if (!gPending) gPending = new std::vector<PendingInsn>();
	gPending->clear();
}

static bool flushPatches() {
	if (!gPending) return true;
	std::vector<PendingInsn> list;
	list.swap(*gPending);
	delete gPending; gPending = nullptr;
	if (list.empty()) return true;
	std::sort(list.begin(), list.end(), [](const PendingInsn& a, const PendingInsn& b) { return a.addr < b.addr; });

	const intptr_t slide = _dyld_get_image_vmaddr_slide(0);
	const uint64_t kMaxSpan = 0x100000;   // 1 MB per write
	const uint64_t kMaxGap  = 0x10000;    // start a new range after a 64 KB gap
	size_t i = 0, ranges = 0;
	std::vector<uint8_t> buf;
	while (i < list.size()) {
		uint64_t start = list[i].addr;
		size_t j = i + 1;
		while (j < list.size() && list[j].addr - list[j - 1].addr <= kMaxGap && list[j].addr + 4 - start <= kMaxSpan) j++;
		uint64_t end = list[j - 1].addr + 4;
		buf.resize(end - start);
		memcpy(buf.data(), (void*)(start + slide), end - start);
		for (size_t k = i; k < j; k++) memcpy(&buf[list[k].addr - start], &list[k].insn, 4);
		write_memory((void*)(start + slide), buf.data(), end - start);
		ranges++;
		i = j;
	}
	// Check every instruction; write any that did not land one by one.
	size_t retried = 0;
	for (const PendingInsn& p : list) {
		if (readInsn(p.addr) != p.insn) {
			retried++;
			write_memory((void*)(p.addr + slide), &p.insn, 4);
			if (readInsn(p.addr) != p.insn) {
				NSLog("[NotEnoughIDsPE] write failed at %llx", p.addr);
				return false;
			}
		}
	}
	NSLog("[NotEnoughIDsPE] wrote %zu instructions in %zu ranges (%zu retried)", list.size(), ranges, retried);
	return true;
}

