static bool patchItemPtr() {
	for (uint64_t addr : kItemTableAddSites) {
		uint32_t insn = readInsn(addr);
		uint32_t rd = insn & 0x1F;
		uint32_t rn = (insn >> 5) & 0x1F;
		// ADD Xd, Xn, #0x238 (64-bit, no shift) and Xd == Xn
		if ((insn & 0xFFFFFC00) != 0x9108E000 || rd != rn) {
			NSLog("[NotEnoughIDsPE] unexpected insn %08x @ %llx", insn, addr);
			return false;
		}
		// LDR Xd, [Xd, #0x240]
		uint32_t ldr = 0xF9400000 | ((0x240 / 8) << 10) | (rd << 5) | rd;
		if (!writeInsn(addr, ldr)) return false;
	}
	return true;
}

