static bool patchItemIdSign() {
	// Check everything first; write nothing unless every site matches.
	std::vector<InsnPatch> patches;
	patches.reserve(sizeof(kItemIdLoadSites) / sizeof(kItemIdLoadSites[0]) + 3);

	for (uint64_t addr : kItemIdLoadSites) {
		uint32_t insn = readInsn(addr);
		uint32_t top = insn & 0xFFC00000;
		uint32_t imm12 = (insn >> 10) & 0xFFF;
		// LDRSH (immediate, unsigned offset): 0x79C00000 (Wt) / 0x79800000 (Xt)
		if ((top != 0x79C00000 && top != 0x79800000) || imm12 != 0x2E / 2) {
			NSLog("[NotEnoughIDsPE] unexpected insn %08x @ %llx", insn, addr);
			return false;
		}
		// LDRH Wt, [Xn, #0x2E]  (zero-extends into the whole Xt as well)
		patches.push_back({ addr, (insn & 0x003FFFFF) | 0x79400000 });
	}

	// ItemInstance::load: SXTH W8, W22 -> UXTH W8, W22
	{
		const uint64_t addr = 0x100759368;
		uint32_t insn = readInsn(addr);
		if ((insn & 0xFFFFFC00) != 0x13003C00) { NSLog("[NotEnoughIDsPE] unexpected insn %08x @ %llx", insn, addr); return false; }
		patches.push_back({ addr, insn | 0x40000000 });
	}
	// BreakingItemParticle: SBFIZ X8, X8, #3, #16 -> UBFIZ X8, X8, #3, #16
	{
		const uint64_t addr = 0x100351B28;
		uint32_t insn = readInsn(addr);
		if ((insn & 0xFFFFFC00) != 0x937D3C00) { NSLog("[NotEnoughIDsPE] unexpected insn %08x @ %llx", insn, addr); return false; }
		patches.push_back({ addr, insn | 0x40000000 });
	}
	// Network read of ItemInstance: SUB W8, W21, #1 / CMP W8, #0x1FE / B.HI invalid
	{
		const uint64_t addr = 0x1004A450C;
		uint32_t insn = readInsn(addr);
		uint32_t rn = (insn >> 5) & 0x1F;
		if (insn != (0x7100001F | (0x1FE << 10) | (rn << 5))) { NSLog("[NotEnoughIDsPE] unexpected insn %08x @ %llx", insn, addr); return false; }
		patches.push_back({ addr, 0x7140001F | (0x10 << 10) | (rn << 5) });   // CMP Wn, #0x10, LSL #12
	}

	for (const InsnPatch& p : patches)
		if (!writeInsn(p.addr, p.newInsn)) return false;
	return true;
}

// ----------------------------------------------------------------------------
//  ItemRenderer::createSingleton  (0x1003CC458)
//  Extend mItemGraphics to 65536 entries as well.
// ----------------------------------------------------------------------------
// Entries 0..255 use the terrain atlas, the rest the items atlas. Block items with
// 16-bit IDs (stage 6) take their icon UVs from the terrain atlas, so their entries
// get the texture of entry 0 (fixBlockItemGraphics, defined with gItemBlock16).
static void fixBlockItemGraphics(size_t first, size_t last);
static void (*_ItemRenderer$createSingleton)(void* textureGroup);
static void ItemRenderer$createSingleton(void* textureGroup) {
	_ItemRenderer$createSingleton(textureGroup);

	size_t oldSize = ItemRenderer$mItemGraphics->size();
	ItemRenderer$mItemGraphics->resize(kMaxItemCount);
	for (size_t i = oldSize; i < (size_t)kMaxItemCount; i++) {
		(*ItemRenderer$mItemGraphics)[i] = (*ItemRenderer$mItemGraphics)[256];
	}
	fixBlockItemGraphics(256, kMaxItemCount);
}

// ============================================================================
//  Block ID expansion - stage 1: block tables (256 -> 65536 entries)
//
//  Real 16-bit block IDs are being added in stages (no BlockExtraData):
//    1. (this stage) every table indexed by block ID gets 65536 entries
//    2. Block::mId (Block+8) becomes 16 bits
//    3. FullBlock / BlockID values carry 16 bits
//    4. chunk storage, saving and networking carry 16 bits
//
//  Stage 1 changes no behaviour: the tables are moved, the IDs are still < 256.
//
//  Every access to these tables is an "ADRP Xn, page / ADD Xd, Xn, #pageoff"
//  pair pointing at the table start (checked: no other kind of reference
//  except one constant store, handled by syncBlockTables). Each ADD becomes
//  "LDR Xd, [Xn, #slot]", where slot is an 8-byte cell inside the old table
//  (block IDs 232..239, unused in vanilla 0.16.2) holding the new table pointer.
//  The old tables are kept equal to the new ones for IDs 0..255, so anything
//  that still reads them gets the right value.
// ============================================================================

