struct BlockTable {
	const char* name;
	uint64_t oldAddr;          // unslid address of the vanilla 256-entry table
	uint32_t elemSize;
	const uint64_t* sites;
	size_t siteCount;
	uint8_t* newTable;         // 65536 entries
};

#define NEID_TABLE(n, addr, size, sites) { n, addr, size, sites, sizeof(sites) / sizeof(sites[0]), nullptr }
static BlockTable gBlockTables[] = {
	NEID_TABLE("Block::mBlocks",         0x1012D1860, 8, kBlockTableSites),
	NEID_TABLE("BlockGraphics::mBlocks", 0x10126A100, 8, kBlockGraphicsTableSites),
	NEID_TABLE("Block::mLightBlock",     0x1012D20A0, 1, kLightBlockSites),
	NEID_TABLE("Block::mLightEmission",  0x1012D21A0, 1, kLightEmissionSites),
	NEID_TABLE("Block::mSolid",          0x1012D22A0, 1, kSolidSites),
	NEID_TABLE("Block::mTranslucency",   0x1012D23A0, 4, kTranslucencySites),
	NEID_TABLE("Block::mShouldTick",     0x1012D27A0, 1, kShouldTickSites),
};
enum { kTabBlocks = 0, kTabGraphics, kTabLightBlock, kTabLightEmission, kTabSolid, kTabTranslucency, kTabShouldTick };

static inline uint8_t* oldTable(const BlockTable& t) { return (uint8_t*)(t.oldAddr + _dyld_get_image_vmaddr_slide(0)); }
static inline uint64_t slotAddr(const BlockTable& t) { return t.oldAddr + kPointerSlotId * t.elemSize; }   // unslid, 8-byte aligned

// Bytes of the old table used by the pointer cell (excluded when mirroring).
static inline bool inSlot(const BlockTable& t, size_t byteOff) {
	size_t s = kPointerSlotId * t.elemSize;
	return byteOff >= s && byteOff < s + 8;
}

static bool patchBlockTables() {
	struct Patch { uint64_t addr; uint32_t insn; };
	std::vector<Patch> patches;

	for (BlockTable& t : gBlockTables) {
		uint64_t slot = slotAddr(t);
		if ((slot & 7) != 0 || (slot & ~0xFFFULL) != (t.oldAddr & ~0xFFFULL)) {
			NSLog("[NotEnoughIDsPE] %s: pointer cell not usable", t.name);
			return false;
		}
		for (size_t i = 0; i < t.siteCount; i++) {
			uint64_t addr = t.sites[i];
			uint32_t adrp = readInsn(addr - 4);
			uint32_t add = readInsn(addr);
			uint32_t rd = add & 0x1F, rn = (add >> 5) & 0x1F;
			// ADRP Xn (any page encoding; checked via the ADD immediate) + ADD Xd, Xn, #(table & 0xFFF)
			uint32_t expectAdd = 0x91000000 | ((uint32_t)(t.oldAddr & 0xFFF) << 10) | (rn << 5) | rd;
			if ((adrp & 0x9F000000) != 0x90000000 || (adrp & 0x1F) != rn || add != expectAdd) {
				NSLog("[NotEnoughIDsPE] %s: unexpected insn %08x %08x @ %llx", t.name, adrp, add, addr);
				return false;
			}
			// LDR Xd, [Xn, #(slot & 0xFFF)]
			patches.push_back({ addr, 0xF9400000 | ((uint32_t)((slot & 0xFFF) / 8) << 10) | (rn << 5) | rd });
		}
	}

	// Allocate the new tables, copy what is already there, then publish the pointers.
	for (BlockTable& t : gBlockTables) {
		t.newTable = (uint8_t*)calloc(kMaxBlockCount, t.elemSize);
		if (!t.newTable) return false;
		memcpy(t.newTable, oldTable(t), 256 * t.elemSize);
		uint8_t* cell = oldTable(t) + kPointerSlotId * t.elemSize;
		for (size_t b = 0; b < 8; b++) t.newTable[kPointerSlotId * t.elemSize + b] = 0;
		*(uint8_t**)cell = t.newTable;
	}
	for (const Patch& p : patches)
		if (!writeInsn(p.addr, p.insn)) return false;
	return true;
}

// After the game has filled the tables: take over anything written to an old
// table by code we did not redirect (the one constant store in Block::initBlocks:
// mTranslucency[0]), then mirror IDs 0..255 back into the old tables.
static void syncBlockTables() {
	for (BlockTable& t : gBlockTables) {
		if (!t.newTable) continue;
		uint8_t* old = oldTable(t);
		for (size_t id = 0; id < 256; id++) {
			size_t off = id * t.elemSize;
			bool touchesSlot = false;
			for (size_t b = 0; b < t.elemSize; b++) if (inSlot(t, off + b)) touchesSlot = true;
			if (touchesSlot) continue;
			bool newEmpty = true;
			for (size_t b = 0; b < t.elemSize; b++) if (t.newTable[off + b]) { newEmpty = false; break; }
			if (newEmpty) memcpy(t.newTable + off, old + off, t.elemSize);
		}
	}
	// mTranslucency[0] is written only through the old table (ADRP + STR #pageoff).
	{
		BlockTable& t = gBlockTables[kTabTranslucency];
		if (t.newTable) memcpy(t.newTable, oldTable(t), 4);
	}
	for (BlockTable& t : gBlockTables) {
		if (!t.newTable) continue;
		uint8_t* old = oldTable(t);
		for (size_t off = 0; off < 256 * t.elemSize; off++)
			if (!inSlot(t, off)) old[off] = t.newTable[off];
	}
}

// ============================================================================
//  Block ID expansion - stage 2: Block::mId (Block+8) is 16 bits
//
//  Block+8 holds the 1-byte block ID and Block+9 is unused padding (no load or
//  store touches it). The constructor's STRB becomes STRH, so +8..+9 hold the
//  16-bit ID (+9 = 0 for vanilla blocks), and every load that reads the ID of a
//  Block becomes a 16-bit load. Loads whose base could not be proven to be a
//  Block on every path are left alone: they keep reading the low byte, which is
//  the same value for IDs below 256.
