extern "C" __attribute__((used)) void neid_getBlockID2(void* region, const int* pos, uint8_t* out) {
	uint8_t* c; uint32_t idx;
	if (!chunkIndexAt(region, pos[0], pos[1], pos[2], &c, &idx)) {
		out[0] = *gDefaultBlockId; out[1] = 0;   // the original stores this default byte
		return;
	}
	uint16_t id = (uint16_t)(c[0xA88 + idx] | (c[kChunkHiOffset + idx] << 8));
	if (!gBlockTable16[id]) id &= 0xFF;
	out[0] = (uint8_t)id;
	out[1] = (uint8_t)(id >> 8);
}
__attribute__((naked, noinline)) static void neid_getBlockID2_entry() {
	__asm__ volatile("mov x2, x8\n b _neid_getBlockID2");
}

static bool widenByteLoad(uint32_t insn, int add, bool toHalf, uint32_t* out) {
	if ((insn & 0xFFC00000) == 0x39400000) {          // LDRB Wt, [Xn, #imm]
		uint32_t imm = ((insn >> 10) & 0xFFF) + add;
		if (!toHalf) { if (imm > 0xFFF) return false; *out = (insn & 0xFFC003FF) | (imm << 10); return true; }
		if (!(imm & 1)) { *out = 0x79400000 | ((imm / 2) << 10) | (insn & 0x3FF); return true; }   // LDRH
		if (imm < 256) { *out = 0x78400000 | (imm << 12) | (insn & 0x3FF); return true; }         // LDURH
		return false;
	}
	if ((insn & 0xFFE00C00) == 0x38400000) {          // LDURB Wt, [Xn, #simm]
		int32_t simm = (int32_t)((insn >> 12) & 0x1FF);
		if (simm & 0x100) simm -= 0x200;
		simm += add;
		if (simm < -256 || simm > 255) return false;
		uint32_t base = toHalf ? 0x78400000 : 0x38400000;   // LDURH / LDURB
		*out = base | (((uint32_t)simm & 0x1FF) << 12) | (insn & 0x3FF);
		return true;
	}
	return false;
}

static int gWideGroups = 0, gWideGroupsSkipped = 0;
static bool patchWideCallers() {
	const intptr_t slide = _dyld_get_image_vmaddr_slide(0);
	const size_t n = sizeof(kWideSites) / sizeof(kWideSites[0]);
	size_t i = 0;
	while (i < n) {
		size_t j = i;
		while (j < n && kWideSites[j].group == kWideSites[i].group) j++;
		std::vector<std::pair<uint64_t, uint32_t>> out;
		bool ok = true;
		for (size_t k = i; k < j && ok; k++) {
			const WideSite& s = kWideSites[k];
			uint32_t insn = readInsn(s.addr), w = 0;
			if (s.type <= 1) {
				uint64_t from = s.type == 0 ? 0x10079A1FC : 0x10079A014;
				uint64_t to = s.type == 0 ? (uint64_t)&neid_getBlockAndData3_entry : (uint64_t)&neid_getBlockID2_entry;
				ok = insn == encBL(s.addr, from) && inBRange(s.addr + slide, to);
				w = encBL(s.addr + slide, to);
			} else {
				ok = widenByteLoad(insn, s.type == 3 ? 1 : 0, s.type == 2, &w);
			}
			if (ok) out.push_back({s.addr, w});
			else neidLog("4c: group %u skipped at %llx (%08x)", s.group, s.addr, insn);
		}
		if (ok) { for (auto& p : out) writeInsn(p.first, p.second); gWideGroups++; }
		else gWideGroupsSkipped++;
		i = j;
	}
	return gWideGroups > 0;
}

// ============================================================================
//  Stage 4e: the remaining 1-byte callers see a stand-in vanilla block
//
//  The getBlockAndData / getBlockID calls that stage 4c could not widen (the
//  result's address is passed on, the slot is reused, the ID is passed to a
//  function or indexes some other table, ...) used to see the low byte of a
//  16-bit ID, i.e. an unrelated vanilla block (300 -> 44 slab, 65535 -> 255).
//  They now call producers with the vanilla layout that report a stand-in
//  ("fallback") vanilla ID for blocks above 255: stone unless the mod sets
//  another with NEID_setBlockFallback. Vanilla blocks read exactly as before.
//
//  Many of these sites read a block, change its data and write it back with
//  setBlockAndData. LevelChunk::setBlockAndData (stage 4b) therefore keeps a
//  16-bit block when the game writes its stand-in or its low byte (not 0 =
//  air) at its position: only the data changes.
// ============================================================================
