static inline uint8_t fallbackIdOf(uint16_t id) {
	return (id > 255 && gBlockTable16[id]) ? gFallbackId[id] : (uint8_t)id;
}
static __thread uint16_t tLastFb16 = 0;   // 16-bit ID behind the last fallback read (7a manual sites)
extern "C" __attribute__((used)) void neid_getBlockAndDataFallback(void* region, const int* pos, uint8_t* out) {
	uint8_t* c; uint32_t idx;
	tLastFb16 = 0;
	if (!chunkIndexAt(region, pos[0], pos[1], pos[2], &c, &idx)) { out[0] = 0; out[1] = 0; return; }
	uint16_t id = (uint16_t)(c[0xA88 + idx] | (c[kChunkHiOffset + idx] << 8));
	tLastFb16 = id;
	uint8_t nib = c[0x8A88 + (idx >> 1)];
	out[0] = fallbackIdOf(id);
	out[1] = (idx & 1) ? (nib >> 4) : (nib & 0xF);
}
__attribute__((naked, noinline)) static void neid_getBlockAndDataFallback_entry() {
	__asm__ volatile("mov x2, x8\n b _neid_getBlockAndDataFallback");
}
extern "C" __attribute__((used)) void neid_getBlockIDFallback(void* region, const int* pos, uint8_t* out) {
	uint8_t* c; uint32_t idx;
	tLastFb16 = 0;
	if (!chunkIndexAt(region, pos[0], pos[1], pos[2], &c, &idx)) { out[0] = *gDefaultBlockId; return; }
	tLastFb16 = (uint16_t)(c[0xA88 + idx] | (c[kChunkHiOffset + idx] << 8));
	out[0] = fallbackIdOf(tLastFb16);
}
__attribute__((naked, noinline)) static void neid_getBlockIDFallback_entry() {
	__asm__ volatile("mov x2, x8\n b _neid_getBlockIDFallback");
}
static __thread uint16_t tLastXyz16 = 0;   // 16-bit ID behind the last getBlockID(x, y, z) fallback read (7a manual sites)
extern "C" __attribute__((used)) void neid_getBlockIDxyzFallback(void* region, int x, int y, int z, uint8_t* out) {
	const int pos[3] = { x, y, z };
	neid_getBlockIDFallback(region, pos, out);
	uint8_t* c; uint32_t idx;
	tLastXyz16 = (region && chunkIndexAt(region, x, y, z, &c, &idx)) ? (uint16_t)(c[0xA88 + idx] | (c[kChunkHiOffset + idx] << 8)) : 0;
}
__attribute__((naked, noinline)) static void neid_getBlockIDxyzFallback_entry() {
	__asm__ volatile("mov x4, x8\n b _neid_getBlockIDxyzFallback");
}

// BlockSource::mayPlace(BlockID const&, pos, face, entity, ...) (0x10079AFFC) looks up
// Block::mBlocks[id] with the ID read as one byte ("LDRB W9, [X23]", 0x10079B054).
// While BlockItem::useOn places a 16-bit block (tPending*, set by the useOn hook),
// that load gives the 16-bit ID, so the block's own mayPlace rules apply.
extern "C" __attribute__((used)) uint32_t neid_mayPlaceId(const uint8_t* id) {
	if (tPendingActive && id[0] == tPendingLo) {
		uint16_t full = (uint16_t)(tPendingLo | (tPendingHi << 8));
		if (full > 255 && gBlockTable16[full]) return full;
	}
	return id[0];
}

